/**
 * Reads .env and syncs Mapbox tokens into local gitignored / generated files.
 *
 * Usage:
 *   cp .env.example .env   # once — paste pk + sk tokens
 *   npm run setup:mapbox # after pull, or automatically on npm install
 *
 * --optional  Exit 0 when .env is missing (postinstall).
 */
const fs = require('fs');
const path = require('path');
const os = require('os');

const root = path.resolve(__dirname, '..');
const optional = process.argv.includes('--optional');

function parseEnv(filePath) {
  const text = fs.readFileSync(filePath, 'utf8');
  const out = {};
  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    let value = trimmed.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    out[key] = value;
  }
  return out;
}

function upsertLocalProperties(filePath, token) {
  let content = fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : '';
  if (/^MAPBOX_DOWNLOADS_TOKEN=/m.test(content)) {
    content = content.replace(/^MAPBOX_DOWNLOADS_TOKEN=.*$/m, `MAPBOX_DOWNLOADS_TOKEN=${token}`);
  } else {
    content = `${content.replace(/\s*$/, '')}\n\nMAPBOX_DOWNLOADS_TOKEN=${token}\n`;
  }
  fs.writeFileSync(filePath, content, 'utf8');
}

function patchInfoPlist(plistPath, pk) {
  let plist = fs.readFileSync(plistPath, 'utf8');
  if (!plist.includes('<key>MBXAccessToken</key>')) {
    throw new Error('MBXAccessToken missing in Info.plist');
  }
  plist = plist.replace(
    /(<key>MBXAccessToken<\/key>\s*<string>)[^<]*(<\/string>)/,
    `$1${pk}$2`,
  );
  fs.writeFileSync(plistPath, plist, 'utf8');
}

function escapeTsString(value) {
  return value.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function main() {
  const envPath = path.join(root, '.env');
  if (!fs.existsSync(envPath)) {
    const msg =
      'No .env file. Run: cp .env.example .env — add MAPBOX tokens — then: npm run setup:mapbox';
    if (optional) {
      console.warn(`[setup:mapbox] ${msg}`);
      process.exit(0);
    }
    console.error(msg);
    process.exit(1);
  }

  const env = parseEnv(envPath);
  const pk = (env.MAPBOX_ACCESS_TOKEN || '').trim();
  const sk = (env.MAPBOX_DOWNLOADS_TOKEN || '').trim();

  if (!pk.startsWith('pk.') || pk.includes('YOUR_')) {
    console.error('Set MAPBOX_ACCESS_TOKEN=pk.… in .env');
    process.exit(optional ? 0 : 1);
  }
  if (!sk.startsWith('sk.') || sk.includes('YOUR_')) {
    console.error('Set MAPBOX_DOWNLOADS_TOKEN=sk.… in .env');
    process.exit(optional ? 0 : 1);
  }

  // JS (gitignored)
  fs.mkdirSync(path.join(root, 'src/config'), { recursive: true });
  fs.writeFileSync(
    path.join(root, 'src/config/env.local.ts'),
    `/** Auto-generated by npm run setup:mapbox — do not commit. */\n` +
      `export const localEnv = {\n` +
      `  MAPBOX_ACCESS_TOKEN: '${escapeTsString(pk)}',\n` +
      `};\n`,
    'utf8',
  );

  // Android public token (gitignored)
  const androidTokenDir = path.join(root, 'android/app/src/main/res/values');
  fs.mkdirSync(androidTokenDir, { recursive: true });
  fs.writeFileSync(
    path.join(androidTokenDir, 'mapbox_access_token.xml'),
    `<?xml version="1.0" encoding="utf-8"?>\n` +
      `<resources xmlns:tools="http://schemas.android.com/tools">\n` +
      `    <string name="mapbox_access_token" translatable="false" tools:ignore="UnusedResources">${pk}</string>\n` +
      `</resources>\n`,
    'utf8',
  );

  // Android downloads token (gitignored via local.properties)
  upsertLocalProperties(path.join(root, 'android/local.properties'), sk);

  // iOS native token (local working copy — do not commit after sync)
  patchInfoPlist(path.join(root, 'ios/DriverTracking/Info.plist'), pk);

  console.log('[setup:mapbox] Synced from .env → env.local.ts, Android XML, local.properties, Info.plist');
  if (process.platform === 'darwin') {
    console.log('[setup:mapbox] Mac/iOS: ensure ~/.netrc has sk token for pod install (see scripts/MAPBOX_NATIVE_SETUP.md)');
  }
}

main();
